+use crate::curve::fees::fee;
+fn transfer<'info>(
+    program: &AccountInfo<'info>,
+    mint: &InterfaceAccount<'info, Mint>,
+    from: &AccountInfo<'info>,
+    to: &AccountInfo<'info>,
