+#[inline(never)]
+fn total_quote(amounts: &[u64; 4]) -> Result<u64> {
+    amounts.iter().try_fold(0u64, |total, amount| {
+        total.checked_add(*amount).ok_or_else(|| error!(PumpAmmError::Overflow))
+    })
