+        .get(0)
+        .ok_or_else(|| error!(PumpAmmError::MissingCashbackAccounts))?;
+    let info = remaining
+        .get(1)
+        .ok_or_else(|| error!(PumpAmmError::MissingCashbackAccounts))?;
