+        require_keys_neq!(self.boost_authority, Pubkey::default(), PumpAmmError::InvalidAdmin);
+        require_keys_eq!(self.boost_authority, *authority, PumpAmmError::InvalidAdmin);
+        Ok(())
+    }
+}

